import argparsefrom matplotlib import pyplot as pltfrom time import perf_counterfrom string import ascii_lowercasedef letter_counter(file_path):    start_time = perf_counter()    count_dict = {character: 0 for character in ascii_lowercase}    with open(file_path) as input_file:        for line in input_file:            for character in line.lower():                try:                    count_dict[character] += 1                except KeyError:                    pass    elapsed_time = perf_counter() - start_time    print(f"Elapsed time is: {elapsed_time:.3f} s")    print(count_dict)    return count_dictif __name__ == "__main__":    parser = argparse.ArgumentParser(        description="Script to count frequence of a letter "        "and show an histogram of it"    )    parser.add_argument(        "--filepath",        default="The republic by Plato.txt",        help="File path to analayze (Default: 'The republic by Plato.txt')",    )    args = parser.parse_args()    count_dict = letter_counter(args.filepath)    plt.title("Histogram of letters frequency")    plt.bar(list(ascii_lowercase), list(count_dict.values()))    plt.show()